import { describe, expect, it } from 'vitest';
import { CreateUserBody, UpdateUserBody, UserIdParams } from '../../src/schemas/user.js';

describe('user schemas', () => {
  it('validates create bodies', () => {
    expect(CreateUserBody.safeParse({ email: 'a@example.com', name: 'A' }).success).toBe(true);
    expect(CreateUserBody.safeParse({ email: 'nope', name: 'A' }).success).toBe(false);
    expect(CreateUserBody.safeParse({ email: 'a@example.com', name: '' }).success).toBe(false);
    expect(CreateUserBody.safeParse({ email: 'a@example.com', name: 'A', id: 'x' }).success).toBe(false);
  });

  it('requires at least one field on update', () => {
    expect(UpdateUserBody.safeParse({}).success).toBe(false);
    expect(UpdateUserBody.safeParse({ name: 'B' }).success).toBe(true);
  });

  it('requires uuid ids', () => {
    expect(UserIdParams.safeParse({ id: 'x' }).success).toBe(false);
  });
});

import request from 'supertest';
import { beforeEach, describe, expect, it } from 'vitest';
import { createApp, type App } from '../../src/app.js';
import { Problem } from '../../src/http/problem.js';
import { usersRoutes } from '../../src/routes/users.js';
import { User, UserPage } from '../../src/schemas/user.js';

const alice = { email: 'alice@example.com', name: 'Alice' };
const missing = '5f0c6b9e-6d5a-4c1b-9a51-0f5c1c9d2e11';

let app: App;
beforeEach(() => {
  app = createApp(usersRoutes());
});

async function create(body: object = alice) {
  return User.parse((await request(app).post('/v1/users').send(body)).body);
}

function problemOf(res: request.Response, status: number) {
  expect(res.status).toBe(status);
  expect(res.get('Content-Type')).toMatch(/^application\/problem\+json/);
  return Problem.parse(res.body);
}

describe('users', () => {
  it('creates: 201 with Location', async () => {
    const res = await request(app).post('/v1/users').send(alice);
    expect(res.status).toBe(201);
    const user = User.parse(res.body);
    expect(user).toMatchObject(alice);
    expect(res.get('Location')).toBe(`/v1/users/${user.id}`);
  });

  it('409s a duplicate email on create and update', async () => {
    const a = await create();
    const b = await create({ email: 'bob@example.com', name: 'Bob' });
    expect(problemOf(await request(app).post('/v1/users').send(alice), 409).instance).toBe('/v1/users');
    problemOf(await request(app).patch(`/v1/users/${b.id}`).send({ email: a.email }), 409);
  });

  it('422s invalid bodies', async () => {
    expect(problemOf(await request(app).post('/v1/users').send({ email: 'x' }), 422).detail).toMatch(/email/);
  });

  it('gets, updates and deletes', async () => {
    const user = await create();
    expect(User.parse((await request(app).get(`/v1/users/${user.id}`)).body)).toEqual(user);
    expect(User.parse((await request(app).patch(`/v1/users/${user.id}`).send({ name: 'Al' })).body).name).toBe('Al');
    const del = await request(app).delete(`/v1/users/${user.id}`);
    expect(del.status).toBe(204);
    expect(del.text).toBe('');
    problemOf(await request(app).get(`/v1/users/${user.id}`), 404);
  });

  it('404s unknown ids on get, update and delete', async () => {
    problemOf(await request(app).get(`/v1/users/${missing}`), 404);
    problemOf(await request(app).patch(`/v1/users/${missing}`).send({ name: 'x' }), 404);
    problemOf(await request(app).delete(`/v1/users/${missing}`), 404);
  });

  it('lists with cursor pagination', async () => {
    for (const n of [1, 2, 3]) await create({ email: `u${n}@example.com`, name: `U${n}` });
    const first = UserPage.parse((await request(app).get('/v1/users?limit=2')).body);
    expect(first.data).toHaveLength(2);
    const second = UserPage.parse((await request(app).get('/v1/users').query({ limit: 2, cursor: first.nextCursor ?? '' })).body);
    expect(second.data.map((u) => u.name)).toEqual(['U3']);
    expect(second.nextCursor).toBeNull();
    problemOf(await request(app).get('/v1/users?limit=0'), 422);
    problemOf(await request(app).get('/v1/users?cursor=garbage!'), 422);
  });

  it('is registered in the default app', async () => {
    expect(createApp().routeTable.map((r) => `${r.method} ${r.path}`)).toContain('post /v1/users');
  });
});

import { z } from 'zod';
import { pageOf } from '../http/pagination.js';

export const User = z.object({
  id: z.uuid(),
  email: z.email(),
  name: z.string().min(1).max(100),
  createdAt: z.iso.datetime(),
});
export type User = z.infer<typeof User>;

export const UserPage = pageOf(User);

export const UserIdParams = z.object({ id: z.uuid() });

export const CreateUserBody = z.strictObject({
  email: z.email(),
  name: z.string().min(1).max(100),
});

export const UpdateUserBody = z
  .strictObject({
    email: z.email().optional(),
    name: z.string().min(1).max(100).optional(),
  })
  .refine((body) => Object.keys(body).length > 0, { message: 'At least one field is required' });

import { randomUUID } from 'node:crypto';
import { ListQuery } from '../http/pagination.js';
import { Conflict, NotFound } from '../http/problem.js';
import { NoContent, defineRoute, type AnyRoute } from '../http/route.js';
import { MemoryStore } from '../http/store.js';
import { CreateUserBody, UpdateUserBody, User, UserIdParams, UserPage } from '../schemas/user.js';

export function usersRoutes(store = new MemoryStore<User>()): AnyRoute[] {
  const emailTaken = (email: string, exceptId?: string) => store.find((u) => u.email === email && u.id !== exceptId) !== undefined;

  const createUser = defineRoute({
    method: 'post',
    path: '/v1/users',
    body: CreateUserBody,
    responses: { 201: User },
    handler: ({ body }) => {
      if (emailTaken(body.email)) throw new Conflict(`A user with email ${body.email} already exists.`);
      const user = store.insert({ id: randomUUID(), email: body.email, name: body.name, createdAt: new Date().toISOString() });
      return { status: 201, body: user, location: `/v1/users/${user.id}` };
    },
  });

  const listUsers = defineRoute({
    method: 'get',
    path: '/v1/users',
    query: ListQuery,
    responses: { 200: UserPage },
    handler: ({ query }) => ({ status: 200, body: store.page(query.cursor, query.limit) }),
  });

  const getUser = defineRoute({
    method: 'get',
    path: '/v1/users/:id',
    params: UserIdParams,
    responses: { 200: User },
    handler: ({ params }) => {
      const user = store.get(params.id);
      if (user === undefined) throw new NotFound(`User ${params.id} does not exist.`);
      return { status: 200, body: user };
    },
  });

  const updateUser = defineRoute({
    method: 'patch',
    path: '/v1/users/:id',
    params: UserIdParams,
    body: UpdateUserBody,
    responses: { 200: User },
    handler: ({ params, body }) => {
      const user = store.get(params.id);
      if (user === undefined) throw new NotFound(`User ${params.id} does not exist.`);
      if (body.email !== undefined && emailTaken(body.email, user.id)) throw new Conflict(`A user with email ${body.email} already exists.`);
      const updated = store.replace(user.id, { ...user, ...body });
      return { status: 200, body: updated };
    },
  });

  const deleteUser = defineRoute({
    method: 'delete',
    path: '/v1/users/:id',
    params: UserIdParams,
    responses: { 204: NoContent },
    handler: ({ params }) => {
      if (!store.delete(params.id)) throw new NotFound(`User ${params.id} does not exist.`);
      return { status: 204 };
    },
  });

  return [createUser, listUsers, getUser, updateUser, deleteUser];
}

export default usersRoutes();
